<?= $this->extend('layouts/admin') ?>
<?= $this->section('content') ?>
<div class="d-flex justify-content-between mb-3 flex-wrap gap-2"><div class="d-flex gap-2 align-items-center flex-wrap"><select id="projectFilter" class="form-select form-select-sm" style="width:200px"><option value="">All Projects</option><?php foreach($projects as $p): ?><option value="<?= $p['id'] ?>"><?= esc($p['name']) ?></option><?php endforeach; ?></select><div class="btn-group"><button class="btn btn-sm btn-outline-secondary filter-btn active" data-status="">All</button><?php foreach(['todo'=>'To Do','in_progress'=>'In Progress','code_review'=>'Code Review','qa'=>'QA','client_review'=>'Client Review','blocked'=>'Blocked','done'=>'Done'] as $s=>$label): ?><button class="btn btn-sm btn-outline-secondary filter-btn" data-status="<?= $s ?>"><?= $label ?></button><?php endforeach; ?></div></div><div class="d-flex gap-2"><a href="<?= base_url('admin/tasks/kanban') ?>" class="btn btn-outline-secondary btn-sm"><i class="bi bi-kanban me-1"></i>Kanban</a><button class="btn btn-primary btn-sm" data-bs-toggle="modal" data-bs-target="#addTaskModal"><i class="bi bi-plus-lg me-1"></i>Add Task</button></div></div>
<div class="card border-0 shadow-sm"><div class="card-body p-0"><div class="table-responsive"><table class="table table-hover align-middle mb-0" id="tasksTable"><thead class="table-light"><tr><th>Task</th><th>Project</th><th>Priority</th><th>Status</th><th>Due Date</th><th>Actions</th></tr></thead><tbody><?php foreach($tasks as $task): ?><?php $sc=['todo'=>'secondary','in_progress'=>'primary','code_review'=>'info','qa'=>'warning','client_review'=>'dark','blocked'=>'danger','done'=>'success'][$task['status']]??'secondary';$pc=['low'=>'success','medium'=>'secondary','high'=>'warning','urgent'=>'danger'][$task['priority']??'medium']??'secondary';$overdue=!empty($task['due_date'])&&$task['due_date']!=='0000-00-00'&&strtotime($task['due_date'])<time()&&!in_array($task['status'],['done','cancelled'],true); ?><tr><td><a href="<?= base_url('admin/tasks?view='.(int)$task['id']) ?>" class="fw-semibold text-decoration-none"><?= esc($task['title']) ?></a><?php if(!empty($task['description'])): ?><div class="text-muted small"><?= esc(substr($task['description'],0,60)) ?>...</div><?php endif; ?></td><td><a href="<?= base_url('admin/projects/'.$task['project_id']) ?>" class="text-decoration-none small"><?= esc($task['project_name']??'—') ?></a><?php if(!empty($task['milestone_title'])):?><div class="text-muted" style="font-size:11px"><i class="bi bi-flag me-1"></i><?= esc($task['milestone_title']) ?></div><?php endif;?></td><td><span class="badge bg-<?= $pc ?>"><?= ucfirst($task['priority']??'medium') ?></span></td><td><select class="form-select form-select-sm task-status-sel" data-id="<?= $task['id'] ?>" style="width:135px"><?php foreach(TaskModel::STATUSES as $s): ?><option value="<?= $s ?>" <?= $task['status']===$s?'selected':'' ?>><?= ucwords(str_replace('_',' ',$s)) ?></option><?php endforeach; ?></select></td><td class="<?= $overdue?'text-danger fw-semibold':'' ?> small"><?= !empty($task['due_date'])&&$task['due_date']!=='0000-00-00'?date('d M Y',strtotime($task['due_date'])):'—' ?><?php if($overdue): ?><span class="badge bg-danger ms-1">Overdue</span><?php endif;?></td><td><a class="btn btn-xs btn-outline-primary me-1" href="<?= base_url('admin/tasks?view='.(int)$task['id']) ?>"><i class="bi bi-eye"></i></a><button class="btn btn-xs btn-outline-danger btn-del-task" data-id="<?= $task['id'] ?>"><i class="bi bi-trash"></i></button></td></tr><?php endforeach;?></tbody></table></div></div></div>
<?= $this->endSection() ?>
<?= $this->section('scripts') ?><script>const BASE='<?= base_url() ?>';$('#tasksTable').DataTable({pageLength:25,order:[[4,'asc']]});$('.task-status-sel').on('change',function(){$.post(`${BASE}admin/tasks/status/${$(this).data('id')}`,{status:$(this).val(),csrf_test_name:getCsrfToken()},r=>showToast(r.message,r.status),'json')});</script><?= $this->endSection() ?>
